      ^MPSGraphTensor*(MPSGraph* graph, NSArray<MPSGraphTensor*>* args) {
        return mps::MpsPowByScalar(
            graph, args[0], other, self_c.scalar_type());
      });
  if (!ran) {
    return at::pow(self.cpu(), other).to(self.device());
  }
  return out;
}

